// ── BEFORE: SRP violation ───────────────────────────────────────
class UserServiceBad {
  save(user)   { /* write to DB */ }
  sendEmail(u) { /* call SMTP */ }    // ← unrelated concern
  toCsv(users) { return users.map(u => `${u.id},${u.name}`).join('\n'); } // ← unrelated
}

// ── AFTER: one responsibility each ─────────────────────────────
class UserRepository  { save(user)   { /* write to DB */ } }
class EmailService    { send(to, msg){ /* call SMTP   */ } }
class UserCsvExporter { export(users){ return users.map(u => `${u.id},${u.name}`).join('\n'); } }

// ── OCP: Strategy-based discount (no editing PriceCalculator) ───
const discounts = {
  none:     () => 0,
  student:  (price) => price * 0.1,
  employee: (price) => price * 0.25,
};
function calcPrice(price, discountType) {
  const discount = discounts[discountType] ?? discounts.none;
  return price - discount(price);
}
// Adding 'vip' discount = one new entry in discounts; calcPrice is untouched.
discounts.vip = (price) => price * 0.3;
console.log(calcPrice(100, 'vip'));      // 70
console.log(calcPrice(100, 'student')); // 90

// ── DIP: inject dependency, don't hardcode it ───────────────────
class OrderService {
  constructor(paymentGateway) {   // ← accepts abstraction
    this._gw = paymentGateway;
  }
  placeOrder(amount) {
    this._gw.charge(amount);
    console.log(`Order placed for $${amount}`);
  }
}
const stripe = { charge: (amt) => console.log(`Stripe charged $${amt}`) };
const paypal = { charge: (amt) => console.log(`PayPal charged $${amt}`) };

const orderWithStripe = new OrderService(stripe);
orderWithStripe.placeOrder(50); // Stripe charged $50

const orderWithPayPal = new OrderService(paypal);
orderWithPayPal.placeOrder(50); // PayPal charged $50

// ── DRY: extract duplicated logic ───────────────────────────────
// BAD — same validation duplicated
function registerUser(email, age) {
  if (!email.includes('@')) throw new Error('Invalid email');
  if (age < 18) throw new Error('Must be 18+');
}
function updateProfile(email, age) {
  if (!email.includes('@')) throw new Error('Invalid email'); // duplicate!
  if (age < 18) throw new Error('Must be 18+');              // duplicate!
}
// GOOD — single source of truth
function validateUserInput(email, age) {
  if (!email.includes('@')) throw new Error('Invalid email');
  if (age < 18) throw new Error('Must be 18+');
}
function registerUser2(email, age) { validateUserInput(email, age); /* ... */ }
function updateProfile2(email, age) { validateUserInput(email, age); /* ... */ }

// ── KISS: simplest correct solution ────────────────────────────
// BAD — over-engineered
function isEven_bad(n) { return n % 2 === 0 ? true : false; } // ternary is redundant
// GOOD
const isEven = (n) => n % 2 === 0;

// ── YAGNI: don't build what isn't needed yet ───────────────────
// BAD — built a plugin system before any plugin was ever requested
class PluginManager { register(p){} run(name){} listAll(){} /* ... 80 lines */ }
// GOOD — start with a plain function; add abstraction only when the second use case arrives
function processPayment(amount) { /* direct implementation */ }

// ── Small functions — rule of thumb: one screen, one purpose ───
// BAD — 40-line monolith
// GOOD — composed small functions
const formatCurrency = (n) => `$${n.toFixed(2)}`;
const applyTax      = (n, rate) => n * (1 + rate);
const calcTotal     = (items, taxRate) =>
  formatCurrency(applyTax(items.reduce((s, i) => s + i.price, 0), taxRate));

console.log(calcTotal([{ price: 9.99 }, { price: 4.99 }], 0.1)); // $16.48
